const r=await tools.exec_command({cmd:"node --input-type=module <<'NODE'
import { chromium } from '@playwright/test'

const browser = await chromium.launch({ headless: true })
const errors = []
const context = await browser.newContext({ viewport: { width: 360, height: 800 } })
const page = await context.newPage()
page.on('pageerror', error => errors.push(error.message))
await page.goto('http://127.0.0.1:4173')
const cards = page.getByRole('button', { name: /Row \d+, column \d+,/ })
if (await cards.count() !== 16) throw new Error('Expected 16 card buttons')
const first = page.getByRole('button', { name: 'Row 1, column 1, closed' })
if ((await first.getAttribute('aria-label')) !== 'Row 1, column 1, closed') throw new Error('Closed card name is wrong')
await first.click()
if (!(await page.getByRole('button', { name: /^Row 1, column 1, .* revealed$/ }).count())) throw new Error('Reveal did not expose a named face')
if (!(await page.getByText('Moves: 0')).count()) throw new Error('First card should not count as a move')
await page.getByRole('button', { name: 'Restart' }).click()
const firstAgain = page.getByRole('button', { name: 'Row 1, column 1, closed' })
await firstAgain.focus()
await page.keyboard.press('ArrowRight')
const second = page.getByRole('button', { name: 'Row 1, column 2, closed' })
if (!(await second.evaluate(node => node === document.activeElement))) throw new Error('ArrowRight did not move focus')
await page.keyboard.press('Enter')
if (!(await page.getByText('Moves: 0')).count()) throw new Error('First keyboard reveal counted as a move')
await page.getByText('Reproduce a game').click()
const snapshot = JSON.stringify({ version: 1, boardCode: 'np1-4-1', matched: [0, 11], selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 120 }, moves: 2, elapsedMs: 1500, started: true })
await page.getByLabel('Snapshot JSON').fill(snapshot)
await page.getByRole('button', { name: 'Load snapshot' }).click()
if (await page.getByText('Loaded snapshot. Select Resume to continue.').count() !== 1) throw new Error('Snapshot load status missing')
const pausedLabel = await page.getByRole('button', { name: /^Row 1, column 2,/ }).getAttribute('aria-label')
await page.getByRole('button', { name: 'Resume' }).click()
if (!(await page.getByRole('button', { name: 'Row 1, column 1, cyan solid circle, marker top, matched' }).evaluate(node => node === document.activeElement))) throw new Error('Resume did not focus the remembered first board card')
await page.waitForTimeout(180)
if (!(await page.getByRole('button', { name: 'Row 1, column 2, magenta solid square, marker top-right, closed' }).count())) throw new Error('Mismatch did not close after resume time')
await page.getByLabel('Grid size').selectOption('16')
const geometry = await page.evaluate(() => {
  const area = document.querySelector('.board-scroll')
  const card = document.querySelector('.card-button')
  if (!area || !card) return null
  return { width: document.documentElement.scrollWidth, viewport: innerWidth, card: card.getBoundingClientRect().width, scrollWidth: area.scrollWidth, clientWidth: area.clientWidth, count: document.querySelectorAll('.card-button').length }
})
if (!geometry || geometry.width > geometry.viewport || geometry.card < 44 || geometry.scrollWidth <= geometry.clientWidth || geometry.count !== 256) throw new Error(`16x16 narrow layout failed: ${JSON.stringify(geometry)}`)
if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`)
console.log(JSON.stringify({ ok: true, geometry, pausedCardBeforeResume: pausedLabel, browser: await browser.version() }))
await context.close()
const offline = await browser.newContext({ offline: true })
const localPage = await offline.newPage()
const localErrors = []
localPage.on('pageerror', error => localErrors.push(error.message))
await localPage.goto('file:///work/dist/index.html')
if (await localPage.getByRole('button', { name: /Row 1, column 1,/ }).count() !== 1 || localErrors.length) throw new Error(`Offline file failed: ${localErrors.join('; ')}`)
console.log('offline file launch passed')
await offline.close()
await browser.close()
NODE",workdir:"/work",yield_time_ms:30000,max_output_tokens:5000});
text(r);

