@import './board/board.css';
@import './controls/controls.css';

:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  line-height: 24px;
  color: #F4F6FF;
  background: #090B14;
  font-synthesis: none;
}

* { box-sizing: border-box; }
html, body, #root { min-height: 100%; margin: 0; width: 100%; }
body { min-width: 0; overflow-x: hidden; }
button, input, select, textarea { font: inherit; }
p, h1 { margin: 0; }

.game-shell {
  width: min(100%, 1120px);
  margin: 0 auto;
  padding: 16px;
}

.game-header { margin-bottom: 24px; }
.game-header h1 { font-size: 24px; line-height: 32px; margin-bottom: 8px; }
.game-header p { color: #B8BDD2; font-size: 14px; line-height: 20px; }

.game-status {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  margin: 16px 0;
